function colorz() {
	const {java, source} = this;
	let cb = '151E27', cf = 'dddddd';
	//★getLoginInfoMap() 在部分环境返回普通 JS 对象（无 .get），需双通道
	function pick(m, k) {
		if (!m) return '';
		try { if (typeof m.get == 'function') return String(m.get(k) || ''); } catch(e) {}
		try { return String(m[k] || ''); } catch(e2) {}
		return '';
	}
	let m = {};
	try { m = source.getLoginInfoMap() || {}; } catch(e) {}
	let v1 = pick(m, '封面背景颜色');
	let v2 = pick(m, '封面字体颜色');
	if (v1 && v1 != 'null' && v1 != 'undefined') cb = v1;
	if (v2 && v2 != 'null' && v2 != 'undefined') cf = v2;
	return [cb, cf];
}

u_a = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/135.0.0.0 Safari/537.36 Edg/135.0.0.0';
x_r_w = ''; //com.microsoft.emmx
s_c_u_p = `"Windows"`;
