function gethdi(url) {
const {java, source, cookie} = this;
//★空值直接返回，避免拼出 "undefined,{...}"
let _u = String(url==null?'':url);
if (!_u || _u=='undefined' || _u=='null') return '';
if (_u.indexOf(',{') >= 0) return _u;
let surl=this.getsurl();
let hd={};
//★年龄确认闸门：不带 age18_ok=1 时全站只返回「年龄确认」页
hd["Cookie"]="age18_ok=1";
hd["Accept-Language"]="zh-CN,zh;q=0.9,en-US;q=0.8,en;q=0.7";
hd["Referer"]=surl;
if (/http.{4}www/.test(surl))
hd["User-Agent"]=u_a;
else {
let ua=java.getWebViewUA()+'';
hd["User-Agent"]=ua;}
hd["Sec-Fetch-Dest"]="image";
hd["Sec-Fetch-Mode"]="no-cors";
hd["Sec-Fetch-Site"]="cross-site";
return url+','+JSON.stringify({"headers":hd});
}
function gethd() {
const {java, source, cookie} = this;
let surl=this.getsurl();
let hd={};
//★年龄确认闸门：CookieJar 里必须常驻 age18_ok=1
//★不能再用 cookie.removeCookie(surl) —— 它会把 age18_ok 一起清掉，
//★导致 java.ajax 走 CookieJar 时拿不到该 Cookie 而被 302 到 age_verify.php
try {
	let ck = String(cookie.getCookie(surl) || '');
	if (ck.indexOf('age18_ok') < 0) {
		cookie.setCookie(surl, ck ? (ck + '; age18_ok=1') : 'age18_ok=1');
	}
} catch(e) { java.log('写 age18_ok 失败：'+e); }
hd["Cookie"]="age18_ok=1";
hd["Accept-Language"]="zh-CN,zh;q=0.9,en-US;q=0.8,en;q=0.7";
hd["Referer"]=surl;
if (/http.{4}www/.test(surl))
hd["User-Agent"]=u_a;
else {
let ua=java.getWebViewUA()+'';
let v=(ua.match(/Chrome\/(\d+)/)||[,'136'])[1];
hd["User-Agent"]=ua;
hd["Sec-CH-UA-Platform"]=`"Android"`;
hd["Sec-CH-UA"]=`"Chromium";v="${v}", "Android WebView";v="${v}", "Not.A/Brand";v="99"`;
hd["Sec-CH-UA-Mobile"]="?1";}
return hd;
}
// ★可用站点池（来自发布页 https://8xsk.org 实测，2026-10-20）
var BX_POOL = ['https://8xsk.cc','https://18xsk.com','https://18xsk.cc','https://bachashuku.org','https://bachashuku.com'];
// ★已失效的旧域名（自动回退，避免用户手填后卡死）
var BX_DEAD = ['www.8xbook.org','8xbook.org','luoyacheng.ip-ddns.com','ip-ddns.com'];

function bxSiteOk(u){
	const {java} = this;
	try {
		let hd={'User-Agent':this.gethd()['User-Agent']||'Mozilla/5.0','Cookie':'age18_ok=1'};
		let b=String(java.connect(u+','+JSON.stringify({headers:hd,timeout:9000})).body());
		return b.length>3000 && b.indexOf('年龄确认')<0 && b.indexOf('八叉')>=0;
	} catch(e) { return false; }
}

function getsurl() {
	const {java, source} = this;
	let surl=String((source.getLoginInfoMap()||{'网址':''})['网址']||'');
	surl=surl.replace(/\/$/,'');
	// 空 → 用默认活站点
	if (!surl) return 'https://8xsk.cc';
	// 已知死域名 → 自动回退
	let dead = BX_DEAD.some(function(d){ return surl.indexOf(d)>=0; });
	if (dead) {
		for (let i=0;i<BX_POOL.length;i++) {
			if (this.bxSiteOk(BX_POOL[i])) { java.log('旧域名已失效，自动切换：'+BX_POOL[i]); return BX_POOL[i]; }
		}
		return 'https://8xsk.cc';
	}
	return surl;
}


function decodeEmail(n, c) {
	//★输入非法（非 hex / 空）时返回空串，不要抛异常
	try {
		function hexToInt(e, t) {
			var r = e.substr(t, 2);
			return parseInt(r, 16);
		}
		let s = String(n == null ? '' : n);
		if (!s || s.length < (c + 4)) return '';
		var o = '', a = hexToInt(s, c), i = c + 2;
		if (isNaN(a)) return '';
		for (i; i < s.length; i += 2) {
			var l = hexToInt(s, i) ^ a;
			if (isNaN(l)) break;
			o += String.fromCharCode(l);
		}
		try { o = decodeURIComponent(escape(o)); } catch(e1) {}
		return o;
	} catch(e) { return ''; }
}


