            str.slice(7)
        ].filter(s => s);
    } else if (length < 20) {
        return [
            str.slice(0, 7),
            str.slice(7,13),
            str.slice(13)
        ].filter(s => s);
    }  else if (length < 24) {
        return [
            str.slice(0, 7),
            str.slice(7,13),
            str.slice(13,18),
            str.slice(18)
        ].filter(s => s);
    } else {
        return [
            str.slice(0, 7),
            str.slice(7, 13),
            str.slice(13, 18),
