	try {
		java.startBrowserAwait(nn + '/login.php,' + JSON.stringify(option), '八叉登录', false);
	} catch(e) {
		java.longToast('打开浏览器失败：' + String(e).substring(0,60)); return;
	}
	Packages.java.lang.Thread.sleep(300);
	//★关键：从 CookieJar 读，而不是响应头
	let ck = '';
	try { ck = String(cookie.getCookie(nn) || ''); } catch(e) {}
	if (ck.indexOf('jieqiUserInfo') >= 0 && ck.indexOf('jieqiUserInfo=deleted') < 0) {
		source.putLoginHeader(JSON.stringify({Cookie: ck}));
		java.longToast('\n✅ 网页登录成功\nVIP模式💎');
	} else {
		java.longToast('\n❌ 未检测到登录 Cookie\n\n可能原因：\n1) 浏览器里没登录成功\n2) 登录后提前返回了\n\n可再点一次「🌐网页登录」，登录成功后停留 2 秒再返回');
	}
}

function ceshi(){
	const {java, source, cookie} = this;
	let nn = getsurl();
	let option = {};
	option["headers"] = gethd();
	java.toast('测试线路：' + nn);
	let lines = [];
	let t0 = new Date().getTime();
	try {
		let web = java.connect(nn + ',' + JSON.stringify(option));
		let ms = new Date().getTime() - t0;
		let body = String(web.body() || '');
		let code = web.code();
		lines.push('线路：' + nn);
		lines.push('状态码：' + code);
		lines.push('耗时：' + (ms/1000).toFixed(2) + ' 秒');
		lines.push('大小：' + body.length + ' B');
		if (code == 403) lines.push('❌ 访问被拒绝');
		else if (code == 520) lines.push('❌ IP 被拉黑');
		else if (body.length < 3000) lines.push('❌ 返回异常（可能被年龄确认拦截）');
		else if (body.indexOf('年龄确认') >= 0) lines.push('❌ 被年龄确认拦截（Cookie 未生效）');
		else if (body.indexOf('八叉') >= 0) lines.push('✅ 正常');
		else lines.push('⚠️ 内容异常');
		// 顺带报告登录态
		let ck = '';
		try { ck = String(cookie.getCookie(nn) || ''); } catch(e) {}
		lines.push('Cookie：' + (ck.indexOf('jieqiUserInfo') >= 0 ? '已登录💎' : '访客🔒'));
	} catch(err) {
		lines.push('❌ 连接失败');
		lines.push(String(err).substring(0, 100));
	}
	java.longToast(lines.join('\n'));
}

