function webck(){
	const {java, source, cookie} = this;
	let nn = getsurl();
	let nnm = nn.replace('www.','');
	let ck = ckget(source);
	//★关键：cookie.setCookie 是「整体替换」语义，直接写登录头会把 age18_ok 清掉
	//★导致浏览器打开后又是「年龄确认」页 → 表现为「打开网站/书架失效」
	try {
		let cur = String(cookie.getCookie(nnm) || '');
		let merged = '';
		if (cur && cur.indexOf('age18_ok') >= 0) merged = cur;
		else merged = cur ? (cur + '; age18_ok=1') : 'age18_ok=1';
		if (ck && merged.indexOf('jieqiUserInfo') < 0) {
			// 把登录头的键合并进去（保留 age18_ok）
			let parts = ck.split(';');
			for (let i = 0; i < parts.length; i++) {
				let kv = String(parts[i]).replace(/^\s+|\s+$/g, '');
				if (!kv || kv.indexOf('=') <= 0) continue;
				let k = kv.substring(0, kv.indexOf('='));
				if (k == 'age18_ok') continue;
				if (merged.indexOf(k + '=') >= 0) continue;
				merged += '; ' + kv;
			}
		}
		cookie.setCookie(nnm, merged);
		try { cache.put('8xbff', source.getLoginInfo()); } catch(e1) {}
		try { cache.put('8xbff2', ck); } catch(e1) {}
	} catch(e) {}
	return nnm;
}

function webb(){
	const {java, source, cache, cookie} = this;
	// 1. 取书籍 id（缓存 → 当前 book）
	let id = '', bkName = '';
	try {
		let m = cache.getFromMemory('8xid');
		if (m) { let k = Object.keys(m)[0]; id = String(k); bkName = String(m[k] || ''); }
	} catch(e) {}
	if (!id) {
		try {
			let bu = String((typeof book != 'undefined' && book) ? (book.bookUrl || '') : '');
			let mm = bu.match(/book[/](\d+)/);
			if (mm) { id = mm[1]; bkName = String(book.name || ''); }
		} catch(e2) {}
	}
	if (!id) {
		java.longToast('\n未获取到书籍 ID\n\n请先打开一本书的详情页\n或在书架里点进书籍后重试');
		return;
	}
	// 2. 同步 Cookie（保证 age18_ok 在）
	let site = webck();
	let jar = String(cookie.getCookie(site) || 'age18_ok=1');
	let bkUrl = site + '/book/' + id + '.html';
	// 3. 优先系统浏览器（内置 WebView 可能被墙）
	let opened = false;
	try {
		java.openUrl(bkUrl);
		opened = true;
		java.toast('已用系统浏览器打开《' + (bkName || id) + '》');
	} catch(e3) {}
	if (!opened) {
		try {
			let ua = java.getWebViewUA();
			java.startBrowser(bkUrl + ',' + JSON.stringify({headers:{'User-Agent':ua,'Cookie':jar}}), '八叉');
			opened = true;
		} catch(e4) {}
	}
	if (!opened) java.longToast('打开失败\n请手动复制网址：\n' + bkUrl);
}

// ===== 📚 把当前书籍加入网站书架（纯 HTTP，不用浏览器）=====
function addsh(){
	const {java, source, cache, cookie} = this;
	// 取书籍 id
	let id = '', bkName = '';
	try {
		let m = cache.getFromMemory('8xid');
		if (m) { let k = Object.keys(m)[0]; id = String(k); bkName = String(m[k] || ''); }
	} catch(e) {}
	if (!id) {
		try {
			let bu = String((typeof book != 'undefined' && book) ? (book.bookUrl || '') : '');
			let mm = bu.match(/book[/](\d+)/);
			if (mm) { id = mm[1]; bkName = String(book.name || ''); }
		} catch(e2) {}
	}
	if (!id) {
		java.longToast('\n未获取到书籍 ID\n\n请先打开一本书的详情页'); return;
	}
	let site = webck();
	let jar = String(cookie.getCookie(site) || '');
	if (jar.indexOf('jieqiUserInfo') < 0) {
		java.longToast('\n❌ 请先登录\n\n加入网站书架需要登录账号'); return;
	}
	java.toast('正在加入网站书架…');
	let ua = java.getWebViewUA();
	let tm = new Date().getTime();
	let body = 'bid=' + id + '&ajax_request=' + tm;
	let opt = {
		headers: {'User-Agent': ua, 'Cookie': jar, 'Referer': site + '/book/' + id + '.html'},
		method: 'POST', body: body, timeout: 25000
	};
	let msg = '';
	try {
		let r = java.connect(site + '/modules/article/addbookcase.php,' + JSON.stringify(opt));
		msg = String(r.body() || '').replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
	} catch(e3) {
		java.longToast('加入失败：' + String(e3).substring(0,80)); return;
	}
	java.log('addbookcase 返回：' + msg);
	if (msg.indexOf('恭喜') >= 0 || msg.indexOf('已经加入') >= 0 || msg.indexOf('已在') >= 0) {
		java.longToast('\n✅ ' + msg + '\n\n《' + (bkName || id) + '》');
	} else {
		java.longToast('\n⚠️ 返回：' + (msg || '空响应') + '\n\n可点「♻️同步书架」核对');
	}
}

// ===== 📚 从网站书架移除当前书籍 =====
function delsh(){
	const {java, source, cache, cookie} = this;
	let id = '';
	try {
		let m = cache.getFromMemory('8xid');
		if (m) { id = String(Object.keys(m)[0]); }
	} catch(e) {}
	if (!id) {
		try {
			let bu = String((typeof book != 'undefined' && book) ? (book.bookUrl || '') : '');
			let mm = bu.match(/book[/](\d+)/);
			if (mm) id = mm[1];
		} catch(e2) {}
	}
	if (!id) { java.longToast('未获取到书籍 ID'); return; }
	let site = webck();
	let jar = String(cookie.getCookie(site) || '');
	if (jar.indexOf('jieqiUserInfo') < 0) { java.longToast('请先登录'); return; }
	let ua = java.getWebViewUA();
	let tm = new Date().getTime();
	let body = 'bid=' + id + '&ajax_request=' + tm;
