function webbs(x){
	const {java, source, cookie} = this;
	let nm = webck();
	let jar = String(cookie.getCookie(nm) || 'age18_ok=1');
	let ua = java.getWebViewUA();

	// ============ x=1：同步网站书架（纯 HTTP，不用浏览器）============
	if (x == 1) {
		// 1. 检查登录
		if (jar.indexOf('jieqiUserInfo') < 0) {
			java.longToast('\n❌ 请先登录\n\n同步书架需要登录账号\n点「🔺登　录🔺」或「🌐网页登录」');
			return;
		}
		java.toast('正在读取网站书架…');
		let b = '';
		try {
			b = String(java.connect(nm + '/modules/article/bookcase.php,{"headers":{"User-Agent":"' + ua + '","Cookie":"' + jar + '"},"timeout":25000}').body() || '');
		} catch(e) {
			java.longToast('读取书架失败：' + String(e).substring(0,60)); return;
		}
		if (!b || b.length < 1000) {
			java.longToast('书架页异常（' + (b?b.length:0) + 'B）\n请检查网络或换线路'); return;
		}
		if (b.indexOf('frmlogin') >= 0) {
			java.longToast('❌ 未登录或登录已失效\n请重新登录'); return;
		}
		// 2. 解析书架里的书
		//★真实结构：div.c_row.cf 卡片 → div.row_text h4 a 是书名（href 带 aid=N）
		//★aid 才是书籍 id；bid 是站点内部 id，不能用来拼 /book/
		let ids = [], names = [], seen = {};
		try {
			let j = Packages.org.jsoup.Jsoup.parse(b);
			let cards = j.select('div.c_row.cf');
			if (cards.size() > 0) {
				for (let i = 0; i < cards.size(); i++) {
					let c = cards.get(i);
					let a = c.select('div.row_text h4 a').first();
					if (a == null) a = c.select('a[href*=aid=]').first();
					if (a == null) continue;
					let href = String(a.attr('href') || '');
					let mm = href.match(/[?&]aid=(\d+)/);
					if (!mm) continue;
					let id = mm[1];
					if (seen[id]) continue;
					seen[id] = 1;
					ids.push(id);
					names.push(String(a.text() || '').replace(/^\s+|\s+$/g, ''));
				}
			}
			// 兜底：没有 c_row 卡片时全页扫
			if (!ids.length) {
				let as = j.select('a[href*=aid=]');
				for (let i2 = 0; i2 < as.size(); i2++) {
					let a2 = as.get(i2);
					let mm2 = String(a2.attr('href') || '').match(/[?&]aid=(\d+)/);
					if (!mm2 || seen[mm2[1]]) continue;
					seen[mm2[1]] = 1;
					ids.push(mm2[1]);
					names.push(String(a2.text() || '').replace(/^\s+|\s+$/g, ''));
				}
			}
		} catch(e2) {
			java.log('解析书架失败：' + e2);
		}
		// 兜底：正则扫
		if (!ids.length) {
			let re = /[?&]aid=(\d+)/g, m3;
			while ((m3 = re.exec(b)) !== null) {
				if (!seen[m3[1]]) { seen[m3[1]] = 1; ids.push(m3[1]); names.push(''); }
			}
		}
		if (!ids.length) {
			java.longToast('书架里没有书\n\n可先点「🌐打开网站」在网页里加书'); return;
		}
		// 3. 逐本加入 Legado 书架
		let okN = 0;
		for (let k = 0; k < ids.length; k++) {
			let bkUrl = nm + '/book/' + ids[k] + '.html';
			let dl = 'legado://import/addToBookshelf?src=' + encodeURIComponent(bkUrl) + ',{"origin":"https://八叉书库.luoyacheng.ip-ddns.com"}';
			try { java.openUrl(dl); okN++; } catch(e3) {}
			// 间隔，避免深链连发被系统吞
			if (k < ids.length - 1) { try { Packages.java.lang.Thread.sleep(700); } catch(e4) {} }
		}
		let preview = [];
		for (let p = 0; p < Math.min(3, ids.length); p++) {
			preview.push('· ' + (names[p] || ids[p]));
		}
		if (ids.length > 3) preview.push('· …等 ' + ids.length + ' 本');
		java.longToast('\n✅ 网站书架共 ' + ids.length + ' 本\n已发起加入 ' + okN + ' 本\n────────\n'
			+ preview.join('\n') + '\n────────\n若未全部加入，可重复点此按钮');
		return;
	}

	// ============ x=2：打开网站（优先系统浏览器）============
	let target = nm;
	let opt = JSON.stringify({headers:{'User-Agent': ua, 'Cookie': jar}});
	let opened = false;
	// 优先用系统浏览器（内置 WebView 可能被墙）
	try {
		java.openUrl(target);
		opened = true;
		java.toast('已用系统浏览器打开');
	} catch(e) {}
	if (!opened) {
		try { java.startBrowser(target + ',' + opt, '八叉'); opened = true; } catch(e2) {}
	}
	if (!opened) java.longToast('打开失败\n请手动在浏览器访问：\n' + target);
}

