// ===== 取表单值：result 优先，退回 getLoginInfoMap（loginUrl 环境可能没有 result）=====
function lgForm(){
	const {java, source} = this;
	let u='', p='';
	try { u = String(result['账号'] || ''); } catch(e) {}
	try { p = String(result['密码'] || ''); } catch(e) {}
	if (!u || !p) {
		try {
			let m = source.getLoginInfoMap() || {};
			if (!u) u = String(m['账号'] || '');
			if (!p) p = String(m['密码'] || '');
		} catch(e2) {}
	}
	return {u: u.replace(/^\s+|\s+$/g,''), p: p};
}

function login(){}
function Login(){
	const {java, source, cookie} = this;
	if (String(source.getLoginHeader()).includes("jieqiUserInfo")) {
		java.longToast('已登录\n如需换号请先点「♤登出」');
		return;
	}
	let surl = getsurl();
	//★先看 CookieJar 里是否已经有登录态（用户可能之前已登录成功，只是登录头没同步）
	let preCk = '';
	try { preCk = String(cookie.getCookie(surl) || ''); } catch(e) {}
	if (preCk.indexOf('jieqiUserInfo') >= 0 && preCk.indexOf('jieqiUserInfo=deleted') < 0) {
		source.putLoginHeader(JSON.stringify({Cookie: preCk}));
		java.longToast('\n✅ 检测到已登录的 Cookie，已自动同步\nVIP模式💎');
		return;
	}
	source.removeLoginHeader();
	java.toast('正在获取验证码…');

	// ---- 1. 打开登录页，拿验证码地址 ----
	let option = {};
	option["headers"] = gethd();
	let lgHtml = '';
	try { lgHtml = String(java.ajax(surl + '/login.php,' + JSON.stringify(option))); } catch(e) {
		java.longToast('登录页打不开：' + String(e).substring(0,60)); return;
	}
	if (!lgHtml || lgHtml.length < 500) {
		java.longToast('登录页异常（' + (lgHtml?lgHtml.length:0) + 'B）\n请先点「🚀一键选站」'); return;
	}

	// ---- 2. 解析验证码地址 ----
	let codeUrl = '';
	try {
		//★八叉的验证码地址不在 img@src（是空的），而在：
		//  input#checkcode 的 onfocus = "this.form.imgccode.src='https://.../checkcode.php?rand=NNN'"
		//  img[name=imgccode] 的 onclick = "this.src='.../checkcode.php?rand='+Math.random()"
		let wj = Packages.org.jsoup.Jsoup.parse(lgHtml);
		let cands = [
			String(wj.select('#checkcode').attr('onfocus') || ''),
			String(wj.select('img[name=imgccode]').attr('onclick') || ''),
			String(wj.select('#t_imgccode').attr('onclick') || ''),
			String(wj.select('img[name~=img.*code]').attr('onclick') || ''),
			String(wj.select('img[name~=img.*code]').attr('onfocus') || '')
		];
		for (let ci = 0; ci < cands.length; ci++) {
			let oc = cands[ci];
			if (!oc) continue;
			let mm = oc.match(/['"]([^'"]*checkcode\.php[^'"]*)['"]/i);
			if (!mm) continue;
			codeUrl = mm[1];
			if (codeUrl.indexOf('http') != 0) codeUrl = surl + '/' + codeUrl.replace(/^[/]+/, '');
			codeUrl = codeUrl.replace(/[+].*$/, '');   // 去掉 +Math.random()
			if (codeUrl) break;
		}
		// 兜底：直接扫 HTML 里的 checkcode.php?rand=数字
		if (!codeUrl) {
			let m2 = lgHtml.match(/checkcode\.php\?rand=[0-9]*/i);
			if (m2) codeUrl = surl + '/' + m2[0];
		}
		// 再兜底：自己拼（站点固定路径）
		if (!codeUrl) codeUrl = surl + '/checkcode.php?rand=' + Math.floor(Math.random()*1e9);
	} catch(e) { java.log('解析验证码地址失败：' + e); }

	if (!codeUrl) {
		java.longToast('💔 未找到验证码地址\n请改用「🌐网页登录」'); return;
	}
	java.log('验证码地址：' + codeUrl);

	// ---- 3. 让用户输入验证码 ----
	let code = '';
	try {
		code = String(java.getVerificationCode(codeUrl + ',' + JSON.stringify(option)) || '').replace(/^\s+|\s+$/g, '');
	} catch(e) {
		java.longToast('验证码弹窗失败：' + String(e).substring(0,60)); return;
	}
	if (!code) { java.longToast('未输入验证码，已取消'); return; }

	let f = lgForm();
	let un = f.u;
	let pw = f.p;
	if (!un || !pw) { java.longToast('💔 账号和密码不能为空'); return; }

	// ---- 4. POST 登录（表单字段与站点 frmlogin 一致）----
	let body = 'username=' + encodeURIComponent(un)
	         + '&password=' + encodeURIComponent(pw)
	         + '&checkcode=' + encodeURIComponent(code)
	         + '&usecookie=2592000&act=login&submit=';
	let opt2 = {};
	opt2["headers"] = gethd();
	opt2["headers"]["Referer"] = surl + '/login.php';
	opt2["method"] = "POST";
	opt2["body"] = body;
	java.toast('登录中…');

	let resp = null, respCode = 0, respBody = '';
	try {
		resp = java.connect(surl + '/login.php?do=submit&jumpurl=' + encodeURIComponent(surl + '/') + ',' + JSON.stringify(opt2));
		respCode = resp.code();
		respBody = String(resp.body() || '');
	} catch(e) {
		java.longToast('登录请求异常：' + String(e).substring(0,80)); return;
	}

	// ---- 5. ★关键：从 CookieJar 读 Cookie（不再用 headers().values("Set-Cookie")）----
	let ck = '';
	try { ck = String(cookie.getCookie(surl) || ''); } catch(e) {}
	// CookieJar 为空时，退回从响应头读（兼容旧行为）
	if (ck.indexOf('jieqiUserInfo') < 0) {
		try {
			let raw = String(resp.headers().get('Set-Cookie') || '');
			if (raw && raw != 'null') {
				let parts = raw.split(',');
				let buf = [];
				for (let i = 0; i < parts.length; i++) {
					let seg = String(parts[i]).replace(/;.*$/, '').replace(/^\s+|\s+$/g, '');
					if (seg && seg.indexOf('=') > 0) buf.push(seg);
				}
				if (buf.length) {
					ck = buf.join('; ');
					cookie.setCookie(surl, ck);
				}
			}
		} catch(e2) {}
	}

	// ---- 6. 判定登录结果 ----
	let ok = ck.indexOf('jieqiUserInfo') >= 0 && ck.indexOf('jieqiUserInfo=deleted') < 0;
	if (ok) {
		source.putLoginHeader(JSON.stringify({Cookie: ck}));
		try {
			let m = source.getLoginInfoMap() || {};
			m['账号'] = un; m['密码'] = pw;
			source.putLoginInfo(JSON.stringify(m));
		} catch(e) {}
		let nm = '';
		let mn = ck.match(/jieqiUserName%3D([^%]+)/) || ck.match(/jieqiUserName=([^;,]+)/);
		if (mn) { try { nm = decodeURIComponent(mn[1]); } catch(e3) { nm = mn[1]; } }
		java.longToast('\n✅ 登录成功' + (nm ? ('：' + nm) : '') + '\nVIP模式💎');
		return;
	}

	// ---- 7. 失败诊断：给出可操作原因 ----
	let reason = '';
	if (respBody.indexOf('验证码错误') >= 0) reason = '验证码错误（请重新点登录，注意区分大小写）';
	else if (respBody.indexOf('验证码') >= 0) reason = '验证码错误';
	else if (respBody.indexOf('密码错误') >= 0 || respBody.indexOf('密码不正确') >= 0) reason = '账号或密码错误';
	else if (respBody.indexOf('不存在') >= 0) reason = '账号不存在';
	else if (respBody.indexOf('frmlogin') >= 0) reason = '仍停在登录页（凭据未通过）';
	else if (respCode == 403) reason = '访问被拒绝(403)';
	else if (respCode >= 500) reason = '服务端错误(' + respCode + ')';
	else if (!respBody) reason = '响应为空';
	else reason = '未知（响应 ' + respBody.length + 'B）';
	java.longToast('\n❌ 登录失败\n原因：' + reason
		+ '\n\n可改用「🌐网页登录」\n（在浏览器里登录后自动同步 Cookie）');
	java.log('登录失败：code=' + respCode + ' body=' + respBody.substring(0, 400));
}

