function webck(){
	const {java, source, cookie} = this;
	let nn = getsurl();
	let nnm = nn.replace('www.','');
	let ck = ckget(source);
	//★关键：cookie.setCookie 是「整体替换」语义，直接写登录头会把 age18_ok 清掉
	//★导致浏览器打开后又是「年龄确认」页 → 表现为「打开网站/书架失效」
	try {
		let cur = String(cookie.getCookie(nnm) || '');
		let merged = '';
		if (cur && cur.indexOf('age18_ok') >= 0) merged = cur;
		else merged = cur ? (cur + '; age18_ok=1') : 'age18_ok=1';
		if (ck && merged.indexOf('jieqiUserInfo') < 0) {
			// 把登录头的键合并进去（保留 age18_ok）
			let parts = ck.split(';');
			for (let i = 0; i < parts.length; i++) {
				let kv = String(parts[i]).replace(/^\s+|\s+$/g, '');
				if (!kv || kv.indexOf('=') <= 0) continue;
				let k = kv.substring(0, kv.indexOf('='));
				if (k == 'age18_ok') continue;
				if (merged.indexOf(k + '=') >= 0) continue;
				merged += '; ' + kv;
			}
		}
		cookie.setCookie(nnm, merged);
		try { cache.put('8xbff', source.getLoginInfo()); } catch(e1) {}
		try { cache.put('8xbff2', ck); } catch(e1) {}
	} catch(e) {}
	return nnm;
}

